const results = [];
for (const [name, fn, args, src, exp] of CASES) {
  const r = await p.evaluate(([fn, args, src]) => {
    const X = window.__X;
    let a; try { a = args.map(v => {
      if (typeof v === 'string' && /^\/.*\/[a-z]*$/.test(v)) { const m = v.match(/^\/(.*)\/([a-z]*)$/); return new RegExp(m[1], m[2]); }
      if (typeof v === 'string' && v.startsWith('s:')) return new RegExp(v.slice(2));
      return v;
    }); } catch (e) { return { r1: 'ARG-THROW: ' + e.message, r2: '', rules: [] }; }
    let check; try { check = X.checks[fn](...a); } catch (e) { return { r1: 'BUILD-THROW: ' + e.message, r2: '', rules: [] }; }
    const ctx = X.mkCtx(src.html || '', src.css || '', src.js || '');
    let r1, r2;
    try { r1 = check(ctx); } catch (e) { r1 = 'THROW: ' + e.message; }
    try { r2 = check(ctx); } catch (e) { r2 = 'THROW: ' + e.message; }
    return { r1: r1 === true ? true : String(r1), r2: r2 === true ? true : String(r2), rules: ctx.cssRules };
  }, [fn, args, src]);
  const got = r.r1 === true;
  const status = exp === 'note' ? 'NOTE' : (got === exp ? 'ok' : 'MISMATCH');
  results.push({ status, name, fn, args, src, got: r.r1, got2: r.r2, exp, rules: r.rules });
}
const bad = results.filter(r => r.status === 'MISMATCH');
const notes = results.filter(r => r.status === 'NOTE');
console.log('TOTAL', results.length, 'MISMATCH', bad.length, 'NOTE', notes.length, 'ok', results.length - bad.length - notes.length);
for (const r of [...bad, ...notes]) console.log(`[${r.status}] ${r.name}\n     args=${JSON.stringify(r.args)} src=${JSON.stringify(r.src)}\n     got=${JSON.stringify(r.got)} got2=${JSON.stringify(r.got2)} exp=${r.exp} rules=${JSON.stringify(r.rules).slice(0, 300)}`);
await b.close();
